<script setup>import{ref}from'vue';defineProps({modelValue:String,label:String,autocomplete:String,error:String});defineEmits(['update:modelValue']);const visible=ref(false)</script>
<template><label class="lp-label">{{label}}<span class="relative mt-2 block"><input :value="modelValue" :type="visible?'text':'password'" :autocomplete="autocomplete" class="field pr-16" required @input="$emit('update:modelValue',$event.target.value)"><button type="button" class="absolute inset-y-0 right-0 px-4 text-xs font-semibold text-indigo" :aria-label="visible?'Hide password':'Show password'" @click="visible=!visible">{{visible?'Hide':'Show'}}</button></span><span v-if="error" class="lp-error">{{error}}</span></label></template>
